python3 -c '
import glob, json, subprocess

files = sorted(glob.glob("/home/rizz/dev/os-manager/.claude/skills/*/SKILL.md"))
for f in files:
    skill_name = f.split("/")[-2]
    res = subprocess.run(["agent-style", "review", "--audit-only", f], capture_output=True, text=True)
    try:
        data = json.loads(res.stdout)
        violations = [r for r in data.get("rule_results", []) if r.get("violations")]
        print(f"{skill_name}: {len(violations)} rules with violations")
        if violations:
            for v in violations:
                print(f"   Rule: {v.get(\"rule\")}, count: {v.get(\"count\")}, note: {v.get(\"violations\")[:2]}")
    except Exception as e:
        print(f"{skill_name}: JSON parse error: {e}")
'
